        return nodeAt(index).val;
    }

    public void addAtHead(int val) {
        insertBetween(head, head.next, new Node(val));
    }

    public void addAtTail(int val) {
        insertBetween(tail.prev, tail, new Node(val));
    }

    public void addAtIndex(int index, int val) {
        if (index < 0) {
            index = 0;
        }
        if (index > size) {
            return;
        }
        Node next = index == size ? tail : nodeAt(index);
        insertBetween(next.prev, next, new Node(val));
    }

    public void deleteAtIndex(int index) {
        if (index < 0 || index >= size) {
            return;
        }
        unlink(nodeAt(index));
    }

    private Node nodeAt(int index) {
        if (index < size / 2) {
            Node cur = head.next;
            for (int i = 0; i < index; i++) {
                cur = cur.next;
            }
            return cur;
        }
        Node cur = tail.prev;
        for (int i = size - 1; i > index; i--) {
            cur = cur.prev;
        }
        return cur;
    }

    private void insertBetween(Node left, Node right, Node node) {
        node.prev = left;
        node.next = right;
        left.next = node;
        right.prev = node;
        size++;
    }

    private void unlink(Node node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
        size--;
    }
}

