class MyLinkedList {
    private int[] values;
    private int size;

    public MyLinkedList() {
        values = new int[4];
    }

    public int get(int index) {
        if (index < 0 || index >= size) {
            return -1;
        }
        return values[index];
    }

    public void addAtHead(int val) {
        addAtIndex(0, val);
    }

    public void addAtTail(int val) {
        addAtIndex(size, val);
    }

    public void addAtIndex(int index, int val) {
        if (index < 0) {
            index = 0;
        }
        if (index > size) {
            return;
        }
        ensureCapacity(size + 1);
        System.arraycopy(values, index, values, index + 1, size - index);
        values[index] = val;
        size++;
    }

    public void deleteAtIndex(int index) {
        if (index < 0 || index >= size) {
            return;
        }
        System.arraycopy(values, index + 1, values, index, size - index - 1);
        size--;
    }

    private void ensureCapacity(int needed) {
        if (needed <= values.length) {
            return;
        }
        int[] next = new int[values.length * 2];
        System.arraycopy(values, 0, next, 0, size);
        values = next;
    }
}

class MyLinkedList {
    private static final int CAPACITY = 2005;
    private final int[] value = new int[CAPACITY];
    private final int[] prev = new int[CAPACITY];
    private final int[] next = new int[CAPACITY];
    private final int head = 0;
    private final int tail = 1;
    private int nextFree = 2;
    private int size;

    public MyLinkedList() {
        next[head] = tail;
        prev[tail] = head;
        prev[head] = -1;
        next[tail] = -1;
    }

    public int get(int index) {
        if (index < 0 || index >= size) {
            return -1;
        }
        return value[nodeAt(index)];
    }

    public void addAtHead(int val) {
        addAtIndex(0, val);
    }

    public void addAtTail(int val) {
        addAtIndex(size, val);
    }

