            index = 0;
        }
        if (index > size) {
            return;
        }
        int after = index == size ? tail : nodeAt(index);
        int before = prev[after];
        int node = nextFree++;
        value[node] = val;
        prev[node] = before;
        next[node] = after;
        next[before] = node;
        prev[after] = node;
        size++;
    }

    public void deleteAtIndex(int index) {
        if (index < 0 || index >= size) {
            return;
        }
        int node = nodeAt(index);
        int before = prev[node];
        int after = next[node];
        next[before] = after;
        prev[after] = before;
        size--;
    }

    private int nodeAt(int index) {
        if (index < size / 2) {
            int cur = next[head];
            for (int i = 0; i < index; i++) {
                cur = next[cur];
            }
            return cur;
        }
        int cur = prev[tail];
        for (int i = size - 1; i > index; i--) {
            cur = prev[cur];
        }
        return cur;
    }
}
